import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';

/**
 * 表单字段 pattern（非 RHF 表单用；RHF 表单继续用 ui/form 的 FormField/FormItem）：
 * 把「label → 控件 → 说明 → 错误」四段关系固化成一次组装，并统一 a11y 连线：
 * 控件拿到 `id`（label 的 htmlFor 目标）、`aria-describedby`（说明 + 错误）、`aria-invalid`、`aria-required`。
 *
 * 渲染函数形态保证连线一定落在真正的控件元素上——不用 Slot 包裹，
 * 避免 id/aria 挂到包装 div/span 上导致点 label 不聚焦、错误不被朗读。
 *
 * 只依赖 tokens、ui Label 与 React 类型；不感知请求、权限与业务规则。
 */
export interface FieldControlProps {
  id: string;
  'aria-describedby': string | undefined;
  'aria-invalid': boolean | undefined;
  'aria-required': boolean | undefined;
}

export interface FormFieldProps {
  /** 必填：作为控件 id 与 aria-describedby 的命名空间，页面内唯一 */
  id: string;
  label: ReactNode;
  /** 辅助说明（渲染为 muted 小字，并被 aria-describedby 引用） */
  description?: ReactNode;
  /** 校验错误文案（非空即 aria-invalid，并进入 aria-describedby） */
  error?: string;
  required?: boolean;
  className?: string;
  /** 控件渲染函数：把返回的 props 展开到 Input/Textarea/SelectTrigger 上 */
  children: (control: FieldControlProps) => ReactNode;
}

export function FormField({ id, label, description, error, required, className, children }: FormFieldProps) {
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [descriptionId, errorId].filter(Boolean).join(' ') || undefined;

  return (
    <div data-slot="form-field" className={cn('grid gap-1.5', className)}>
      <label
        htmlFor={id}
        className={cn('text-sm leading-[15px] font-medium', error ? 'text-danger' : 'text-foreground')}
      >
        {label}
        {required ? (
          <span aria-hidden className="ml-0.5 text-danger-strong">
            *
          </span>
        ) : null}
      </label>
      {children({
        id,
        'aria-describedby': describedBy,
        'aria-invalid': error ? true : undefined,
        'aria-required': required ? true : undefined,
      })}
      {description ? (
        <p id={descriptionId} className="text-xs leading-[13px] text-muted-foreground">
          {description}
        </p>
      ) : null}
      {error ? (
        <p id={errorId} role="alert" className="text-sm leading-[15px] font-medium text-danger">
          {error}
        </p>
      ) : null}
    </div>
  );
}
